// Actual p56 prime-minus-one F-hold stream, then unknown width-13 ragged columnar transposition.
#define main known_main
#include "solver_generic.cpp"
#undef main
constexpr int HMAX=64,START_H=26,BASE=13;
using Bits=uint64_t;
Tape primeKey(int n){vector<int>p;for(int v=2;(int)p.size()<n;v++){bool ok=true;for(int d=2;d*d<=v;d++)if(v%d==0){ok=false;break;}if(ok)p.push_back((v-1)%A);}return p;}
Tape primeEncrypt(const Tape&p,const Tape&k,int start){Tape c;for(int x:p){if(!x)c.push_back(0);else c.push_back((x+k.at(start++))%A);}return c;}
struct PD{int score=BAD,start=-1,end=-1;Tape plain;};
PD primeDecode(const Tape&c,const Tape&key,const LM&m,int lower,int upper){int K=key.size(),S=K*A;vector<int>d(S,BAD),n(S);for(int p=lower;p<=upper;p++)d[p*A]=0;vector<int16_t>back(c.size()*S,-1);if(S>32767)throw runtime_error("decoder backpointer capacity");for(size_t i=0;i<c.size();i++){fill(n.begin(),n.end(),BAD);bool first=i%W==0;for(int p=lower;p<=upper+(int)i;p++)for(int old=0;old<A;old++){int s=p*A+old;if(d[s]==BAD)continue;auto put=[&](int y,int q){int t=q*A+y,v=d[s]+(first?m.u[y]:m.b[old][y]);if(v>n[t]){n[t]=v;back[i*S+t]=s;}};int y=mod(c[i]-key[p],A);if(y)put(y,p+1);if(!c[i])put(0,p);}d.swap(n);}int s=max_element(d.begin(),d.end())-d.begin();PD z;z.score=d[s];if(z.score==BAD)return z;z.end=s/A;z.plain.resize(c.size());for(int i=(int)c.size()-1;i>=0;i--){z.plain[i]=s%A;s=back[(size_t)i*S+s];assert(s>=0);}z.start=s/A;assert(primeEncrypt(z.plain,key,z.start)==c);return z;}
struct PN{Order o{};int mask=0,rank=BAD;vector<int16_t>s;};
struct PrimeSearch{
 const Tape&key;const LM&lm;int width,H=0;array<array<int,W>,R>c{};array<int,R>zero{},before{},zc{},stride{};array<size_t,R+1>stateOff{};array<vector<Bits>,R>suf;
 PrimeSearch(const Tape&t,int lc,const Tape&k,const LM&m,int bw):key(k),lm(m),width(bw){auto cols=columns(t,lc);int h=START_H;for(int r=0;r<R;r++){before[r]=h;for(int j=0;j<W;j++){c[r][j]=cols[j][r+1];if(!c[r][j])zero[r]|=1<<j;}zc[r]=__builtin_popcount((unsigned)zero[r]);h+=zc[r];stride[r]=h+1;stateOff[r+1]=stateOff[r]+(before[r]+1)*(zc[r]+1)*2;}H=h;if(H>=HMAX)throw runtime_error("hold bitset capacity");for(int r=0;r<R;r++){auto&v=suf[r];int stride_=stride[r];v.resize((size_t)(ALL+1)*stride_);for(int h=0;h<stride_;h++)v[h]=Bits(1)<<h;for(int mask=1;mask<=ALL;mask++){int depth=W-__builtin_popcount((unsigned)mask),hmax=before[r]+__builtin_popcount((unsigned)(zero[r]&~mask));for(int h=0;h<=hmax;h++){int index=BASE+W*(r+1)+depth-h;assert(index>=0&&index<(int)key.size());Bits bits=0;for(unsigned b=mask;b;b&=b-1){int j=__builtin_ctz(b),next=mask^(1<<j),x=c[r][j];if(x!=key[index])bits|=v[(size_t)next*stride_+h];if(!x)bits|=v[(size_t)next*stride_+h+1];}v[(size_t)mask*stride_+h]=bits;}}}}
 size_t si(int r,int h,int l,int held)const{return stateOff[r]+((size_t)h*(zc[r]+1)+l)*2+held;}
 int score(const PN&n,int d)const{array<int,HMAX>enter,next;enter.fill(BAD);for(int h=0;h<=START_H;h++)enter[h]=0;int rem=ALL^n.mask;for(int r=0;r<R;r++){next.fill(BAD);int z=__builtin_popcount((unsigned)(zero[r]&n.mask));for(int h=0;h<=before[r];h++)if(enter[h]>BAD)for(int l=0;l<=z;l++){int v=max(n.s[si(r,h,l,0)],n.s[si(r,h,l,1)]);if(v==NEG)continue;int a=enter[h]+v;for(Bits b=suf[r][(size_t)rem*stride[r]+h+l];b;b&=b-1){int q=__builtin_ctzll(b);next[q]=max(next[q],a);}}enter=next;if(*max_element(enter.begin(),enter.end())==BAD)return BAD;}return *max_element(enter.begin(),enter.end());}
 PN first(int j)const{PN n;n.o[0]=j;n.mask=1<<j;n.s.assign(stateOff[R],NEG);for(int r=0;r<R;r++)for(int h=0;h<=before[r];h++){int ix=BASE+W*(r+1)-h,x=c[r][j],y=mod(x-key[ix],A);if(y)n.s[si(r,h,0,0)]=lm.u[y];if(!x)n.s[si(r,h,1,1)]=lm.u[0];}n.rank=score(n,1);return n;}
 PN extend(const PN&p,int j,int d)const{PN n;n.o=p.o;n.o[d]=j;n.mask=p.mask|(1<<j);n.s.assign(stateOff[R],NEG);int last=p.o[d-1];for(int r=0;r<R;r++){int z=__builtin_popcount((unsigned)(zero[r]&p.mask)),x=c[r][j],old=c[r][last];for(int h=0;h<=before[r];h++)for(int l=0;l<=z;l++){int a=p.s[si(r,h,l,0)],b=p.s[si(r,h,l,1)];if(a==NEG&&b==NEG)continue;int ix=BASE+W*(r+1)+d-h-l,y=mod(x-key[ix],A),pc=a==NEG?0:mod(old-key[ix-1],A);auto add=[&](int dest,int ll,int held){int v=NEG;if(a!=NEG)v=max(v,a+lm.b[pc][dest]);if(b!=NEG)v=max(v,b+lm.b[0][dest]);auto&w=n.s[si(r,h,ll,held)];w=max((int)w,v);};if(y)add(y,l,0);if(!x)add(0,l+1,1);}}n.rank=score(n,d+1);return n;}
 PN run(int lc,const Order*truth=nullptr){vector<PN>beam;auto f=first(lc);if(f.rank==BAD)return f;beam.push_back(move(f));auto better=[](const PN&a,const PN&b){if(a.rank!=b.rank)return a.rank>b.rank;return a.o<b.o;};for(int d=1;d<W;d++){vector<PN>next;next.reserve(width+1);for(auto&p:beam)for(unsigned b=ALL^p.mask;b;b&=b-1){int j=__builtin_ctz(b);PN n=extend(p,j,d);if(n.rank==BAD)continue;if((int)next.size()<width){next.push_back(move(n));push_heap(next.begin(),next.end(),better);}else if(better(n,next.front())){pop_heap(next.begin(),next.end(),better);next.back()=move(n);push_heap(next.begin(),next.end(),better);}}if(next.empty())return PN{};if(truth&&(*truth)[0]==lc){bool yes=false;for(auto&n:next)yes|=equal(n.o.begin(),n.o.begin()+d+1,truth->begin());cerr<<"truth depth "<<d+1<<" kept "<<yes<<"\n";}beam=move(next);}return move(*max_element(beam.begin(),beam.end(),[](auto&a,auto&b){return a.rank<b.rank;}));}
};
int main(int argc,char**argv){if(argc!=5){cerr<<"usage: prime_column tapes.txt control1|control2|original split beam\n";return 1;}auto src=load(argv[1]);string mode=argv[2];int lc=stoi(argv[3]),bw=stoi(argv[4]);Tape k=primeKey(1000),p,c;Order truth{};bool plant=mode!="original";LM m;if(plant){string name=mode=="control1"?"0_koan_1":"0_loss_of_divinity";auto it=find_if(src.begin(),src.end(),[&](const Source&s){return s.name==name;});p=sub(it->t,0,N);m=model(src,name);iota(truth.begin(),truth.end(),0);mt19937 rng(mode=="control1"?3301:3302);shuffle(truth.begin(),truth.end(),rng);c=transpose(primeEncrypt(p,k,0),truth);}else{c=src[0].t;m=model(src,"");}auto t0=chrono::steady_clock::now();PrimeSearch search(c,lc,k,m,bw);PN n=search.run(lc,plant?&truth:nullptr);if(n.rank==BAD){cout<<"NO_LEGAL "<<mode<<" split "<<lc<<"\n";return 0;}Tape e=untranspose(c,n.o);auto tr=primeDecode(sub(e,W,38*W),k,m,0,26);assert(tr.score==n.rank);auto ho=primeDecode(sub(e,38*W,55*W),k,m,tr.end,tr.end);PD full;int chosen=-1;for(int st:{0,12,13}){auto x=primeDecode(e,k,m,st,st);if(x.score>full.score){full=move(x);chosen=st;}}cout<<"WIN "<<mode<<" split "<<lc<<" score "<<tr.score<<" order "<<ordstr(n.o)<<" start "<<tr.start<<" end "<<tr.end<<" holdout "<<ho.score<<" full "<<full.score<<" origin "<<chosen<<" seconds "<<chrono::duration<double>(chrono::steady_clock::now()-t0).count()<<"\n";cout<<"TRAIN "<<enc(tr.plain)<<"\nHELD_BRIDGE "<<enc(ho.plain)<<"\nFULL "<<enc(full.plain)<<"\n";if(full.score>BAD)assert(transpose(primeEncrypt(full.plain,k,full.start),n.o)==c);if(plant)cout<<"PLANT order "<<(n.o==truth)<<" train_exact "<<same(tr.plain,sub(p,W,38*W))<<" held_exact "<<(ho.score==BAD?-1:same(sub(ho.plain,W,17*W),sub(p,39*W,55*W)))<<" full_exact "<<same(full.plain,p)<<" true_order "<<ordstr(truth)<<"\n";}
